  var pedidos = (datos && datos.tablas && datos.tablas.pedidos) || [];
  function esVenta(e) { return e === "confirmado" || e === "enviado" || e === "entregado" || e === "novedad"; }
  var conteo = {};
  for (var i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
