function consultar(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var fmt = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 16).replace("T", " "); };
  var N = 7;
  var limite = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var tablas = (datos && datos.tablas) || {};
  var pedidos = tablas.pedidos || [];
  var clientes = tablas.clientes || [];
  var porCliente = {};
  for (var i = 0; i < clientes.length; i++) {
    var c = clientes[i];
    if (c && c.id) porCliente[c.id] = c.nombre || null;
  }
  var sel = [];
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || p.estado !== "novedad" || !p.creado) continue;
    var d = null;
    try { d = dia(p.creado); } catch (e) { continue; }
    if (d <= limite) continue;
    sel.push(p);
  }
  sel.sort(function (a, b) { return Date.parse(b.creado) - Date.parse(a.creado); });
  var filas = [];
  var n = sel.length > 200 ? 200 : sel.length;
  for (var k = 0; k < n; k++) {
    var q = sel[k];
    var items = q.items || [];
    var partes = [];
    for (var m = 0; m < items.length; m++) {
      var it = items[m] || {};
      var cant = typeof it.cantidad === "number" ? it.cantidad : 1;
      var nom = it.nombre || "Producto";
      partes.push(cant + "x " + nom);
    }
    var nombreCliente = porCliente[q.clienteId] !== undefined ? porCliente[q.clienteId] : null;
    var fechaTxt = null;
    try { fechaTxt = fmt(q.creado); } catch (e) { fechaTxt = null; }
    filas.push({
      numero: typeof q.numero === "number" ? q.numero : null,
      fecha: fechaTxt,
      cliente: nombreCliente,
      ciudad: q.ciudad || null,
      detalle: partes.join(", ") || null,
      total: typeof q.total === "number" ? q.total : null
    });
  }
  return filas;
}

