function calcular(datos) {
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var conteo = {};
  for (var i = 0; i < pedidos.length; i++) {
    var p = pedidos[i];
    if (!p) continue;
    if (p.estado !== "confirmado" && p.estado !== "enviado" && p.estado !== "entregado" && p.estado !== "novedad") continue;
    if (!p.clienteId) continue;
    conteo[p.clienteId] = (conteo[p.clienteId] || 0) + 1;
  }
  var total = 0;
  var repetidos = 0;
  for (var k in conteo) {
    if (Object.prototype.hasOwnProperty.call(conteo, k)) {
      total++;
      if (conteo[k] > 1) repetidos++;
    }
  }
  var pct = total === 0 ? 0 : (repetidos / total) * 100;
  pct = Math.round(pct * 10) / 10;
  return {
    valor: pct,
    unidad: "%",
    nota: repetidos + " de " + total + " compradores repitieron compra en los últimos 60 días; venta es pedido confirmado, enviado, entregado o con novedad."
  };
}

