    acc[p.clienteId].total += t;
    acc[p.clienteId].n += 1;
  }
  var lista = [];
  for (var id in acc) {
    if (Object.prototype.hasOwnProperty.call(acc, id)) {
      lista.push({ id: id, total: acc[id].total, n: acc[id].n });
