  var grupos = {};
  var i;
  for (i = 0; i < mensajes.length; i++) {
    var m = mensajes[i];
    if (!m || !m.clienteId || !m.creado) continue;
    var d = dia(m.creado);
    if (!(d > limite)) continue;
    var k = m.clienteId + "|" + d;
    var g = grupos[k];
    if (!g) { g = { minCliente: null, agentes: [] }; grupos[k] = g; }
    var t = Date.parse(m.creado);
    if (m.rol === "cliente") {
      if (g.minCliente === null || t < g.minCliente) g.minCliente = t;
    } else if (m.rol === "agente") {
      g.agentes.push(t);
    }
  }
  var tiempos = [];
  for (var key in grupos) {
    if (!Object.prototype.hasOwnProperty.call(grupos, key)) continue;
    var gr = grupos[key];
    if (gr.minCliente === null || gr.agentes.length === 0) continue;
    var mejor = null;
    for (var j = 0; j < gr.agentes.length; j++) {
      var ta = gr.agentes[j];
      if (ta > gr.minCliente && (mejor === null || ta < mejor)) mejor = ta;
    }
    if (mejor === null) continue;
    tiempos.push(Math.round((mejor - gr.minCliente) / 1000));
  }
  tiempos.sort(function (a, b) { return a - b; });
  var n = tiempos.length;
  var mediana = null;
  var p90 = null;
  if (n > 0) {
    if (n % 2 === 1) {
      mediana = tiempos[(n - 1) / 2];
    } else {
      mediana = Math.round((tiempos[n / 2 - 1] + tiempos[n / 2]) / 2);
    }
    var idx = Math.ceil(0.9 * n) - 1;
