function calcular(datos) {
  var dia = function (iso) { return new Date(Date.parse(iso) - 5 * 3600 * 1000).toISOString().slice(0, 10); };
  var N = 365;
  var umbral = dia(new Date(Date.parse(datos.hoy) - N * 86400000).toISOString());
  var hoyDia = dia(datos.hoy);
  var tablas = datos.tablas || {};
  var clientes = tablas.clientes || [];
  function mesDeDia(d) { return d.slice(0, 7); }
  var mesInicio = mesDeDia(umbral);
  var mesFin = mesDeDia(hoyDia);
  var y0 = parseInt(mesInicio.slice(0, 4), 10);
  var m0 = parseInt(mesInicio.slice(5, 7), 10);
  var y1 = parseInt(mesFin.slice(0, 4), 10);
  var m1 = parseInt(mesFin.slice(5, 7), 10);
  var meses = [];
  var y = y0;
  var m = m0;
  while (y < y1 || (y === y1 && m <= m1)) {
    var mm = (m < 10 ? "0" + m : "" + m);
    meses.push(y + "-" + mm);
    m += 1;
    if (m > 12) { m = 1; y += 1; }
  }
  var conteo = {};
  for (var i = 0; i < meses.length; i++) { conteo[meses[i]] = 0; }
  var total = 0;
  for (var j = 0; j < clientes.length; j++) {
    var c = clientes[j];
    if (!c || !c.creado) { continue; }
    var d = dia(c.creado);
    if (d > umbral && d <= hoyDia) {
      var mes = d.slice(0, 7);
      if (conteo[mes] === undefined) { conteo[mes] = 0; }
      conteo[mes] += 1;
      total += 1;
    }
  }
  var serie = [];
  for (var k = 0; k < meses.length; k++) {
    serie.push({ etiqueta: meses[k], valor: conteo[meses[k]] || 0 });
  }
  return {
    valor: total,
    unidad: "clientes",
    serie: serie,
    nota: "Clientes nuevos con fecha de creaci\u00f3n en los \u00faltimos 365 d\u00edas, agrupados por mes en hora de Bogot\u00e1."
  };
}

