function consultar(datos) {
  var pedidos = (datos.tablas && datos.tablas.pedidos) || [];
  var clientes = (datos.tablas && datos.tablas.clientes) || [];
  var hoyMs = Date.parse(datos.hoy);
  var nombres = {};
  for (var i = 0; i < clientes.length; i++) {
    nombres[clientes[i].id] = clientes[i].nombre || clientes[i].id;
  }
  function fmtBogota(iso) {
    var d = new Date(Date.parse(iso) - 5 * 3600 * 1000);
    return d.toISOString().slice(0, 16).replace('T', ' ');
  }
  var filas = [];
  for (var j = 0; j < pedidos.length; j++) {
    var p = pedidos[j];
    if (!p || p.estado !== 'pendiente') continue;
    if (!p.creado) continue;
    var creadoMs = Date.parse(p.creado);
    if (isNaN(creadoMs)) continue;
    var diffMs = hoyMs - creadoMs;
    if (diffMs <= 3 * 86400000) continue;
    var dias = Math.floor(diffMs / 86400000);
    filas.push({
      numero: p.numero != null ? p.numero : p.id,
      cliente: nombres[p.clienteId] || p.clienteId,
      ciudad: p.ciudad || '',
      total: typeof p.total === 'number' ? p.total : 0,
      fecha_pedido: fmtBogota(p.creado),
      dias_pendiente: dias,
      _creadoMs: creadoMs
    });
  }
  filas.sort(function(a, b) { return b._creadoMs - a._creadoMs; });
  var out = [];
  var limite = filas.length > 200 ? 200 : filas.length;
  for (var k = 0; k < limite; k++) {
    out.push({
      numero: filas[k].numero,
      cliente: filas[k].cliente,
      ciudad: filas[k].ciudad,
      total: filas[k].total,
      fecha_pedido: filas[k].fecha_pedido,
      dias_pendiente: filas[k].dias_pendiente
    });
  }
  return out;
}

